/* designme.dev theme bridge: the components take their colours and corners from a shadcn/ui or Tailwind v4 theme.
   Load it after the components' CSS, in a project whose theme defines --background, --card, --popover, --foreground, --muted-foreground, --border, --input, --ring, --secondary, --primary, --primary-foreground, --destructive, --chart-1, --chart-2, --chart-3, --chart-4, --chart-5, --radius
   (on :root, and on .dark for dark mode). It changes only the components ([data-dm]), never the rest of the page.
   Dark mode: the theme's .dark values reach the colours it sets here; keep data-theme="dark" on <html> in step with .dark,
   so the rest of the components' tokens (status colours, shadows) switch too. Without this file the components keep their
   own look. */
:where([data-dm]):not(#\#){
  --dm-page:var(--background);
  --dm-stage:var(--background);
  --dm-surface:var(--card);
  --dm-raised:var(--popover);
  --dm-fg:var(--foreground);
  --dm-fg2:color-mix(in oklab,var(--foreground) 70%,var(--muted-foreground));
  --dm-muted:var(--muted-foreground);
  --dm-line:var(--border);
  --dm-rail:var(--border);
  --dm-field-line:var(--input);
  --dm-field-line-strong:var(--ring);
  --dm-focus:var(--ring);
  --dm-chip:var(--secondary);
  --dm-soft:var(--secondary);
  --dm-dis-fill:var(--secondary);
  --dm-hover:color-mix(in oklab,var(--secondary) 88%,var(--foreground));
  --dm-press:color-mix(in oklab,var(--secondary) 82%,var(--foreground));
  --dm-wash:color-mix(in oklab,var(--secondary) 50%,var(--card));
  --dm-row:color-mix(in srgb,var(--foreground) 4%,transparent);
  --dm-accent:var(--primary);
  --dm-on-accent:var(--primary-foreground);
  --dm-accent-fg:var(--primary);
  --dm-accent-mark:var(--primary);
  --dm-accent-2:color-mix(in oklab,var(--primary) 86%,var(--primary-foreground));
  --dm-accent-bg:color-mix(in srgb,var(--primary) 9%,transparent);
  --dm-sel:color-mix(in srgb,var(--primary) 6%,transparent);
  --dm-bad:var(--destructive);
  --dm-c1:var(--chart-1);
  --dm-c2:var(--chart-2);
  --dm-c3:var(--chart-3);
  --dm-c4:var(--chart-4);
  --dm-c5:var(--chart-5);
  --dm-a1:var(--dm-c1);
  --dm-a2:color-mix(in oklab,var(--dm-c1) 72%,var(--dm-surface));
  --dm-a3:color-mix(in oklab,var(--dm-c1) 50%,var(--dm-surface));
  --dm-a4:color-mix(in oklab,var(--dm-c1) 32%,var(--dm-surface));
  --dm-r-card:max(0px,calc(var(--radius) + 4px));
  --dm-r-lg:max(0px,calc(var(--radius) + 4px));
  --dm-r-in:var(--radius);
  --dm-r-box:var(--radius);
  --dm-r-box-sq:var(--radius);
  --dm-r-sm:max(0px,calc(var(--radius) - 2px));
  --dm-r-field:max(0px,calc(var(--radius) - 2px));
  --dm-r-field-sq:max(0px,calc(var(--radius) - 2px));
  --dm-r-xs:max(0px,calc(var(--radius) - 4px));
  --dm-r-tag:max(0px,calc(var(--radius) - 4px));
  --dm-r-tag-sq:max(0px,calc(var(--radius) - 4px));
}
